INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT 'cda88b10-1fbf-546e-8302-5dce37c794f0'::uuid, 'cbe7239f-d180-5102-9969-f2b57cf79591'::uuid, 'Résidence la corniche', 'Résidence la corniche - Kénitra Située au cœur de La Ville Haute à Kénitra, la Résidence la corniche incarne l''élégance et la modernité . Avec son emplacement stratégique à l''angle de la rue Rachid Rida et de la rue Chellah, ce projet résidentiel offre un cadre de vie exceptionnel, pensé pour le confort des familles et des investisseurs. Caractéristiques principales: - Résidence R+6 moderne - Plateaux Bureaux - Locaux Commerciaux - Finitions raffinées et design contemporain La Résidence la corniche se distingue par ses espaces lumineux, ses terrasses agréables et une vue imprenable sur la ville et l''Oued Sebou. C''est l''adresse idéale pour profiter d''un cadre urbain dynamique tout en bénéficiant de la tranquillité d''un logement haut standing.', 'Kénitra', 'La Ville Haute', '5 Angle Rue Rachid Rida et Rue Chella, La Ville Haute, 14000 Kénitra', '14000', 'MA', NULL, NULL, 'immobilier', 'mixte', 'mixte', 'en_construction', 'en_commercialisation', 55, '2026-05', NULL, 'https://media.chridari.ma/46629bf3-7405-415c-acb0-bc6f9fdcb752/images/01KBJGP2917BEDHNWAW20XTQS8-medium.jpg', $j$["https://media.chridari.ma/46629bf3-7405-415c-acb0-bc6f9fdcb752/images/01KBJGP2917BEDHNWAW20XTQS8-medium.jpg", "https://media.chridari.ma/4eb4e788-166c-4bb5-823b-171cfbbbde42/images/01KBJGP0C1D3QTMFKZVC5DN5MW-medium.jpg", "https://media.chridari.ma/145f1bab-f43c-470e-9d73-0fb60cfa87cf/images/01KBJGP3PD853D76TB5GCC0JPT-medium.jpg", "https://media.chridari.m