INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '3a85ceae-8e32-5b89-8a77-1292f086815c'::uuid, 'cbe7239f-d180-5102-9969-f2b57cf79591'::uuid, 'Résidence El musk', 'Résidence El musk - Un art de vivre au cœur de Kénitra La Résidence El musk se distingue comme l''un des projets immobiliers les plus attractifs de Kénitra, au quartier El Mizzane. Ce projet livré en R+4 signé ARENA IMMOBILIER réunit élégance architecturale, confort quotidien et fonctionnalités modernes. Ici, tout a été pensé pour répondre aux besoins variés: - Appartements modernes avec espaces lumineux et finitions soignées. - Bureaux pratiques, idéaux pour professionnels et entrepreneurs. - Locaux commerciaux stratégiques garantissant visibilité et accessibilité. ### Pourquoi choisir Résidence El musk? - Emplacement stratégique à proximité du centre-ville et des commodités essentielles. - Résidence sécurisée avec services intégrés pour un confort optimal. La Résidence El musk incarne la combinaison parfaite entre investissement rentable et cadre de vie agréable, faisant d''elle une valeur sûre sur le marché immobilier de Kénitra.', 'Kénitra', 'Centre Ville', 'Angle de l''avenue Mohammed V et des rues 178 et 308, Centre Ville, 14000 Kénitra', '14000', 'MA', NULL, NULL, 'immobilier', 'mixte', 'mixte', 'livre', 'en_commercialisation', 100, NULL, NULL, 'https://media.chridari.ma/13de7582-7459-44b3-b010-17500dad8b1c/images/01K44SNJY33X8V2V9TD8Y7KFBW-medium.jpg', $j$["https://media.chridari.ma/13de7582-7459-44b3-b010-17500dad8b1c/images/01K44SNJY33X8V2V9TD8Y7KFBW-medium.jpg", "https://media.chridari.ma/cc224e6e-8de8-44bd-87d3-ea4a07c50cf5/im