INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT 'd8809cbd-07ad-5ffa-b53c-c1fcca7d3585'::uuid, '537fe1e8-bf23-53ef-9ac3-94bd067b3857'::uuid, 'The Mansions', 'THE MANSIONS - L''élégance architecturale dans un cadre naturel privilégié THE MANSIONS est un projet résidentiel haut de gamme signé AT 83 Properties, situé sur la route de l''Ourika à Marrakech. Ce domaine privé se compose de 6 villas de luxe, pensées pour offrir un cadre de vie harmonieux entre modernité, confort et nature. ### Un cadre de vie exceptionnel À seulement 15 minutes du centre-ville et 30 minutes de la Vallée de l''Ourika, THE MANSIONS bénéficie d''un emplacement stratégique, alliant proximité urbaine et sérénité absolue. ### Des villas pensées pour l''excellence - 5 suites élégantes aux volumes généreux - Espaces de vie lumineux avec de grandes ouvertures - Jardin privatif arboré et piscine remarquable - Prestations haut standing et finitions raffinées - Architecture aux teintes naturelles parfaitement intégrée au paysage ### L''art de vivre à Marrakech Offrez-vous un quotidien alliant prestige, calme et nature dans un environnement sécurisé et intimiste. Chaque détail des villas THE MANSIONS a été conçu pour répondre aux attentes des plus exigeants.', 'Marrakech', 'Tassoultante', 'Route de l''Ourika, Tassoultante, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'residentiel', 'residentiel', 'en_construction', 'en_commercialisation', 55, '2026-03', NULL, 'https://media.chridari.ma/75d9464d-799a-4f4b-8767-7ba167596bb5/images/01JVPHNY3YY3QXKTAPBVV8RSN2-medium.jpg', $j$["https://media.chridari.ma/75d9464d-799a-4f4b-8767