INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT 'b8e1922b-5482-5a2a-8a26-ba13c0ddf272'::uuid, '08692df2-4d7c-5eca-b242-8229e0c5d661'::uuid, 'Atik Signature', 'Vivez une expérience de vie moderne au cœur de Mhamid, à Marrakech Bienvenue à Atik Signature, un projet résidentiel contemporain conçu pour ceux qui recherchent un parfait équilibre entre confort, élégance et praticité urbaine. Chaque espace est pensé pour offrir des volumes lumineux, fonctionnels et agréables à vivre, créant ainsi une véritable sensation de chez-soi en plein centre-ville. Pourquoi choisir Atik Signature? Emplacement privilégié: idéalement situé sur l''avenue Ghemassa à Mhamid, avec un accès facile aux principaux axes de la ville Design moderne: des résidences intelligemment conçues pour optimiser l''espace, la lumière naturelle et le confort quotidien Environnement paisible: un cadre résidentiel calme au sein d''un quartier en plein développement Vie connectée: proximité des services essentiels, commerces, écoles et commodités du quotidien Qualité de vie : un projet pensé selon des standards modernes, alliant confort et valeur durable Atik Signature est plus qu''une résidence, c''est un véritable choix de vie, combinant architecture contemporaine, emplacement stratégique et bien-être au quotidien dans l''un des quartiers les plus prometteurs de Marrakech.', 'Marrakech', 'M''Hamid', 'Avenue Ghemassa, M''Hamid, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'mixte', 'mixte', 'en_construction', 'en_commercialisation', 55, '2027-12', NULL, 'https://media.chridari.ma/f6d8678b-e4ff-4bcf-a094-f6d8786d22f3/images/01KN1