INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '37004c49-582c-5240-a31d-de42b8ee92bd'::uuid, '08692df2-4d7c-5eca-b242-8229e0c5d661'::uuid, 'Atik Prestige 4', '### Atik Prestige 4 Vivre Marrakech autrement Situé au cœur du quartier dynamique de Mhamid 9 à Marrakech, le projet Atik Prestige 4 vous invite à découvrir un cadre de vie moderne, serein et parfaitement équilibré entre confort urbain et tranquillité. ### Un cadre de vie harmonieux Atik Prestige 4 bénéficie d''un environnement calme et bien organisé, idéal pour les familles comme pour les actifs à la recherche de stabilité et de qualité de vie. Le quartier offre une atmosphère conviviale et sécurisée, propice au bien-être quotidien. ### Une localisation stratégique Implanté dans une zone en plein développement, ce projet vous place à proximité des axes principaux de Marrakech, facilitant vos déplacements au quotidien tout en restant à l''écart de l''agitation excessive du centre-ville. ### Une vie quotidienne simplifiée Vivre à Atik Prestige 4, c''est profiter d''un environnement pratique où tout est pensé pour rendre votre quotidien plus fluide et agréable. - Accès facile aux principales routes - Quartier en pleine expansion - Environnement familial et sécurisé - Cadre idéal pour résidence principale ou investissement ### Un équilibre parfait Entre modernité et sérénité, Atik Prestige 4 représente une opportunité idéale pour ceux qui souhaitent vivre dans un environnement paisible tout en restant connectés à la vie urbaine de Marrakech.', 'Marrakech', 'M''Hamid 9', 'Immeuble Atik Prestige 4, M''Hamid 9, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'residentiel', 'residentiel', 'pret_a_livrer', 'en_commercialisation', 90, '2026-04', NULL, 'https://media.chridari.ma/faf210b6-cda8-4629-abb6-585ca40a2464/images/01KN4F019D74ZMVJE2CH4T41QR-medium.jpg', $j$["https://media.chridari.ma/faf210b6-cda8-4629-abb6-585ca40a2464/images/01KN4F019D74ZMVJE2CH4T41QR-medium.jpg", "https://media.chridari.ma/0fb58faf-f854-479d-b072-2203c75ad794/images/01KN4F028DXBRW0PCE2TSF06RD-medium.jpg", "https://media.chridari.ma/7cb7d901-f4ef-482b-ab41-4d778d7ab677/images/01KN4F038TTYJQTD8WJ4HVNHWQ-medium.jpg", "https://media.chridari.ma/980294ae-edb1-46a2-b0a9-d94edfbd35cb/images/01KN4F044HECEQKG1GX7W5J86G-medium.jpg", "https://media.chridari.ma/1c88a187-2385-4dc0-a3e5-1a3ee8d1e300/images/01KN4QQR9MGMZSAKPC3QHA0BP2-medium.jpg", "https://media.chridari.ma/af6ac827-202a-4f0b-b02c-cdab58f12df9/images/01KN4QQS90D666YC4AJ1352GTQ-medium.jpg"]$j$::jsonb, 'Appartement', 'Balcon ,  Ascenseur ,  Cuisine équipée ,  Parking', 'Banque ,  Aéroport ,  Boulangerie ,  Gare routière ,  Café ,  Clinique ,  Salle de sport ,  Hammam ,  Mosquée ,  Pharmacie ,  École ,  Supermarché ,  Station-service', false, 570000.0, 570000.0, 570000.0, 'MAD', '50 – 67 m2', '08692df2-4d7c-5eca-b242-8229e0c5d661', 'Atik Immobilier', 'https://chridari.ma/fr/promoters/atik-immobilier-74oru9', $j$[]$j$::jsonb, $j${"source_project_id": "37004c49-582c-5240-a31d-de42b8ee92bd", "chridari_ref": "1hepof", "projet_id_legacy": "CHR-PRJ-1hepof", "reference_annonce": "MA202604", "entreprises_construction": "Atik Immobilier (conception et réalisation — site promoteur)", "equipe_realisation_mentions": "Entreprise (medium): Atik Immobilier promoteur-constructeur (atikimmobilier.ma) — Atik Prestige 4", "url_source": "https://chridari.ma/fr/projects/atik-prestige-4-appartement-a-marrakech-1hepof", "chambres_min": "2", "chambres_max": "3", "seed_batch": "promoteurs_full_sifarah"}$j$::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.projects x WHERE x.id = '37004c49-582c-5240-a31d