INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT 'a64275e3-d6da-5810-8d62-49c68d473042'::uuid, '08692df2-4d7c-5eca-b242-8229e0c5d661'::uuid, 'Villa Akenza', '### Villa Akenza Une parenthèse de sérénité à Marrakech Situé sur la route de Tahnaout, le projet Villa Akenza vous offre un cadre de vie unique où calme, nature et confort se rencontrent pour créer une expérience résidentielle exceptionnelle. ### Un environnement paisible Loin de l''agitation du centre-ville, ce projet s''inscrit dans un cadre naturel apaisant, idéal pour se ressourcer et profiter d''un quotidien serein. ### Une immersion dans la nature Entouré de paysages ouverts et d''une atmosphère pure, Villa Akenza permet de vivre dans un environnement où la tranquillité et la beauté naturelle sont au rendez-vous. ### Une qualité de vie authentique Ce projet est parfait pour ceux qui recherchent une vie plus calme, loin du stress urbain, tout en restant connectés à Marrakech. - Cadre naturel et reposant - Atmosphère calme et privée - Environnement propice à la détente - Idéal pour résidence principale ou secondaire ### Un style de vie équilibré Villa Akenza incarne un art de vivre où confort moderne et sérénité naturelle se complètent parfaitement pour offrir une expérience de vie harmonieuse.', 'Marrakech', 'Route de l''Ourika', 'km 5, Route de Tahnaout, à côté de l''Akenza Golf Resort, Route de l''Ourika, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'residentiel', 'residentiel', 'pret_a_livrer', 'en_commercialisation', 90, '2026-04', NULL, 'https://media.chridari.ma/1ce567da-19b1-4677-b3ac-afbdb63bbbb8/images/01KTC7TG9TA6