INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '0f579111-cd7b-5caa-9d70-295f0af0d5a2'::uuid, 'e6461e03-c447-516e-a63e-d76d1bb2374c'::uuid, 'Résidence Al Yassamine', 'Résidences Al Yassamine - Essaouira À seulement 7 km d''Essaouira, les Résidences Al Yassamine offrent un cadre de vie unique entre nature et modernité. Situé à Al Ghazoua, le projet profite d''un climat doux toute l''année et de la proximité immédiate des plages et commodités, idéal pour y vivre ou investir. Cette résidence R+3 de moyen standing séduit par son architecture élégante, ses espaces verts et ses zones sécurisées. Les appartements, spacieux et lumineux, bénéficient de finitions soignées et d''un excellent rapport qualité/prix, avec éligibilité au Daam Sakane (70.000 Dhs). Types d''appartements: - T3 : 77 à 118 m² - à partir de 504.000 Dhs - T4 : 94 à 142 m² - à partir de 629.000 Dhs Équipements du projet : Centre culturel Commerces Écoles & université Espaces verts Aires de jeux Centre de santé Boulangerie - Pâtisserie Centre commercial Mosquée', 'Essaouira', 'Ghazoua', '7km, Route d''Agadir, Ghazoua, 44000 Essaouira', '44000', 'MA', NULL, NULL, 'immobilier', 'residentiel', 'residentiel', 'pret_a_livrer', 'en_commercialisation', 90, '2025-10', NULL, 'https://media.chridari.ma/65d4eeb2-e233-4dbc-944c-58295899e371/images/01JZMQVAAPSD7YQ9DPQ9A0FQKY-medium.jpg', $j$["https://media.chridari.ma/65d4eeb2-e233-4dbc-944c-58295899e371/images/01JZMQVAAPSD7YQ9DPQ9A0FQKY-medium.jpg", "https://media.chridari.ma/5c27eae1-cb46-43b1-9e02-1fa83baaadf7/images/01JZMQVDZZNE4KCED5N9ZN6KKC-medium.jpg", "https://media.chridari.ma/69c2fb9b-536b-4