INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '00dc3385-52f6-504b-9293-11f9d961c8fb'::uuid, 'e6461e03-c447-516e-a63e-d76d1bb2374c'::uuid, 'Résidence Massylia', 'Résidence Massylia - Agadir À partir de 865.000 DH, la Résidence Massylia offre un cadre de vie prestigieux à l''entrée de la ville d''Agadir, en provenance de Marrakech. Idéalement implantée sur l''Avenue Guergarate, dans l''extension du quartier Al Houda, elle bénéficie d''un accès rapide au centre-ville, aux commodités et aux plages. Ce projet résidentiel en R+5 avec piscines et ascenseurs se distingue par une architecture contemporaine et audacieuse, des espaces verts aménagés et des finitions raffinées. Les appartements, spacieux et lumineux, ont été pensés pour allier confort et praticité. Caractéristiques des appartements: - Salon moderne - Cuisine équipée - Balcons avec vue dégagée - Finitions soignées Types et superficies: - T3: de 65 à 69 m² - À partir de 865.000 DH - T4: de 78 à 96 m² - À partir de 935.000 DH Équipements haut de gamme: - Piscines - Espaces verts - Commerces - Établissement scolaire - Mosquée - Parking - Aires de jeux - Centre commercial - Centre d''affaires La Résidence Massylia conjugue design moderne, confort et qualité de vie, dans un environnement calme aux portes d''Agadir.', 'Agadir', 'Tassila', 'Avenue Guergarate, Tassila, 80650 Agadir', '80650', 'MA', NULL, NULL, 'immobilier', 'residentiel', 'residentiel', 'en_construction', 'en_commercialisation', 55, '2026-01', NULL, 'https://media.chridari.ma/5d123c33-575e-4181-abc6-b9389ce0a026/images/01JZMTJ0Q93ECK233F22AFSNKW-medium.jpg', $j$["https://media.chrid