INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '877c81ab-3251-539b-8714-fb23d17ec6ac'::uuid, 'e6461e03-c447-516e-a63e-d76d1bb2374c'::uuid, 'Résidence Dyar Al Bahia', 'Résidence Dyar Al Bahia - Témara À seulement 5 minutes de Rabat, la résidence Dyar Al Bahia propose un cadre de vie moderne et agréable au cœur de Témara, Al Massira II. Son architecture contemporaine et épurée offre un environnement élégant, fonctionnel et confortable au quotidien. Les immeubles R+4 et R+5 disposent d''ascenseurs modernes, d''un parking en sous-sol, et d''appartements lumineux avec des agencements optimisés. Chaque logement comprend : - Salon spacieux - 2 à 3 chambres - Cuisine équipée - Salle de bain et WC séparé - Balcon ou terrasse avec vue sur des patios et jardins verdoyants Types et prix : - T3 : 54–62 m² – à partir de 504.000 Dhs - T4 : 66–80 m² – à partir de 616.000 Dhs Équipements : Centre de santé, espaces verts, poste de police, commerces, parkings, écoles, hammam et équipements socioculturels. Le projet est éligible au programme d''aide directe au logement (70.000 Dhs), idéal pour vivre ou investir avec confort et praticité. Livraison : 3ème trimestre 2025', 'Témara', 'Massira 2', 'Av Lalla Meriem,, Massira 2, 12040 Témara', '12040', 'MA', NULL, NULL, 'immobilier', 'residentiel', 'residentiel', 'en_construction', 'en_commercialisation', 55, '2025-08', NULL, 'https://media.chridari.ma/85fc2366-3162-4d87-9f4c-e4306957d920/images/01JZN4QCKS81ZF5GKPKZGK7N0W-medium.jpg', $j$["https://media.chridari.ma/85fc2366-3162-4d87-9f4c-e4306957d920/images/01JZN4QCKS81ZF5GKPKZGK7N0W-medium.jpg", "https://media.chridari.