dari.ma/fr/projects/residence-dyar-al-bahia-appartement-temara-4v15c0", "chambres_min": "2", "chambres_max": "3", "seed_batch": "promoteurs_full_sifarah"}$j$::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.projects x WHERE x.id = '877c81ab-3251-539b-8714-fb23d17ec6ac'::uuid OR x.attributes->>'source_project_id' = '877c81ab-3251-539b-8714-fb23d17ec6ac');
INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT 'c511f33e-14b2-5748-bd22-f6ecb0cd8533'::uuid, 'e6461e03-c447-516e-a63e-d76d1bb2374c'::uuid, 'Résidence Jnane Souss', 'Résidence Jnane Souss - Agadir À partir de 730.000 DH, la Résidence Jnane Souss propose un cadre de vie moderne et fonctionnel à Tassila, extension du quartier Al Houda à Agadir. Située à proximité de toutes les commodités, des transports en commun et des plages, elle allie confort, praticité et élégance. Conçus avec des matériaux de qualité et des espaces optimisés, les appartements comprennent: - 2 à 3 chambres avec salon lumineux - Cuisine équipée avec buanderie - 2 salles de bain + toilettes de service - Balcon privé pour profiter d''un extérieur Composée d''immeubles en R+5 avec ascenseurs et parkings souterrains, la résidence offre également des commerces, espaces verts, école, mosquée, aires de jeux, centre commercial et centre d''affaires. Types et superficies des appartements: - T3: de 68 à 77 m² - À partir de 730.000 DH - T4: de 70 à 94 m² - À partir de 740.000 DH Livraison prévue au 1er trimestre 2026. Une belle opportunité pour investir ou vivre dans un quartier en plein essor à Agadir.', 'Agadir', 'Tassila', 'Avenue Guergarate, Tassila, 80000 Agadir', '80000', 'MA', NULL, NULL, 'immobilier', 'residentiel', 'residentiel', 'en_construction', 'en_commercialisation', 55, '2026-01', NULL, 'https://media.chridari.ma/e460f28e-6ccd-4eff-ab04-8489940710ea/images/01JZN5KBPTC1JB5Z7V3PJSMJ0V-medium.jpg', $j$["https://media.chridari.ma/e460f28e-6ccd-4eff-ab04-8489940710ea/images/01JZN5KBPTC1JB5Z7V3PJSMJ0V-medium.jpg", "https://media.c