-52bu6t", "chambres_min": "2", "chambres_max": "3", "seed_batch": "promoteurs_full_sifarah"}$j$::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.projects x WHERE x.id = 'c511f33e-14b2-5748-bd22-f6ecb0cd8533'::uuid OR x.attributes->>'source_project_id' = 'c511f33e-14b2-5748-bd22-f6ecb0cd8533');
INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '1088a841-234c-5359-8c77-42e63f032d53'::uuid, 'e6461e03-c447-516e-a63e-d76d1bb2374c'::uuid, 'Résidence Al Araar', 'Al Araar - Essaouira Ne construisez pas seulement une maison, créez un art de vivre. À Al Araâr, au calme de Al Ghazoua, à seulement quelques minutes d''Essaouira, profitez de lots de villas viabilisés avec deux façades, pour donner vie à la villa de vos rêves. Un cadre naturel, la brise marine et un microclimat doux toute l''année — l''équilibre parfait entre confort et évasion. Superficies de 162 à 248 m² À partir de 680.400 Dhs (4.200 Dhs/m²) Lots prêts pour R+1 Équipements du projet : Aires de jeux pour enfants Boulangerie - Pâtisserie Écoles & université Centre de santé & mosquée Équipements socioculturels Résidence principale, maison de vacances ou investissement rentable - Al Araâr est votre opportunité.', 'Essaouira', 'Ghazoua', '7km, Route d''Agadir, Ghazoua, 44000 Essaouira', '44000', 'MA', NULL, NULL, 'immobilier', 'lotissement', 'lotissement', 'pret_a_livrer', 'en_commercialisation', 90, NULL, NULL, 'https://media.chridari.ma/b41e1476-4b2a-4154-9909-30fbff3073cc/images/01JZN8EX76B9GBYC4WKPNJ0A2X-medium.jpg', $j$["https://media.chridari.ma/b41e1476-4b2a-4154-9909-30fbff3073cc/images/01JZN8EX76B9GBYC4WKPNJ0A2X-medium.jpg", "https://media.chridari.ma/f0b27247-1365-410f-9213-fd1edf553dd7/images/01JZN8EVXFQMRG914814E7HYD5-medium.jpg", "https://media.chridari.ma/8d7f16ae-597a-4e10-b3df-dc427628601c/images/01JZN8EWB70TNJ4M3V72FD8BGY-medium.jpg", "https://media.chridari.ma/ea4d7c6b-9b3f-4228-926a-60b16d9de38b/images/01JZN8EWS1PXZDRF90DRK80DMN-medium.jpg"]$j$::jsonb, 'Terrain', 'Climatisation ,  Cuisine équipée ,  Mosquée', 'Boulangerie ,  Clinique ,  Mosquée ,  École ,  Centre commercial ,  Université', false, 680000.0, 680000.0, 680400.0, 'MAD', '162 – 248 m2', 'e6461e03-c447-516e-a63e-d76d1bb2374c', 'Chaabi Lil Iskane', 'https://www.liliskane.com/', $j$[]$j$::jsonb, $j${"source_project_id": "1088a841-234c-5359-8c77-42e63f032d53", "chridari_ref": "bjqka6", "projet_id_legacy": "CHR-PRJ-bjqka6", "reference_annonce": "ES843593", "bureau_etudes": "Direction Études et Développement — Chaabi Lil Iskane (interne)", "equipe_realisation_mentions": "Études / architecture interne: Direction Études et Développement Chaabi Lil Iskane | Architectes chefs de projet cités LinkedIn (groupe, non rattachés projet par projet): Amir O. (senior, Marrakech-Safi); Ihsane Bennani | Architecte (medium): Faouzi Kharchafi — programme Essaouira El Jadida / Al Ghazoua (Aujourd'hui le Maroc 2003 + fiche liliskane Al Araâr)", "url_source": "https://chridari.ma/fr/projects/residence-al-araar-terrain-villa-essaouira-bjqka6", "seed_batch": "promoteurs_full_sifarah"}$j$::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.projects x WHERE x.id = '1088a841-234c-5359-8c77-42e63f032d53'::uuid OR x.attributes->>'source_project_id' = '1088a841-234c-5359-8c77-42e63f032d53');
INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT 'a3a71f8a-d547-5788-a706-410b57d86163'::uuid, 'e6461e03-c447-516e-a63e-d76d1bb2374c'::uuid, 'Résidence Al Anbra', 'Résidence Al Anbra - Essaouira À partir de 903.000 DH, la Résidence Al Anbra est située à Al Ghazoua, au sein du programme Essaouira El Jadida, à seulement quelques minutes de la médina. Entre mer, nature et authenticité, elle propose un cadre calme et préservé, tout en restant proche des principales commodités, le choix idéal pour une résidence principale ou secondaire. Avec son design raffiné en R+3, ses lignes épurées, sa luminosité naturelle et ses espaces paysagers, Al Anbra crée un cadre agréable et durable, avec des finitions de standing. Appartements (97 à 111 m²): - Salon spacieux - 3 chambres, dont une suite parentale avec dressing et salle de bain privative - Seconde salle de bain - Cuisine équipée - Grandes baies vitrées donnant sur la piscine et les jardins Équipements du projet: - Piscine - Espaces verts - Aires de jeux - Parking aérien - Mosquée - Hammam - Supermarché - Coffee shop - Boulangerie–pâtisserie - Écoles & université - Équipements socioculturels La Résidence Al Anbra allie confort moderne et authenticité de la vie à Essaouira.', 'Essaouira', 'Ghazoua', '7km, Route d''Agadir, Ghazoua, 44000 Essaouira', '44000', 'MA', NULL, NULL, 'immobilier', 'residentiel', 'residentiel', 'en_construction', 'en_commercialisation', 55, '2027-07', NULL, 'https://media.chridari.ma/39606dfc-12fe-4b89-b348-841de903e4d9/images/01JZQB1FBJ9CG3TXGQWBEM4QB3-medium.jpg', $j$["https://media.chridari.ma/39606dfc-12fe-4b89-b348-841de903e4d9/im