INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '6a14a0c7-352a-5d1c-86ed-239ee12a1712'::uuid, '5b4b7c60-58f6-5e3b-a4f6-212d255052c0'::uuid, 'Résidence Miftah', 'Résidence Miftah - Votre nouveau départ à Marrakech Située au cœur de Mhamid 9, à seulement quelques minutes de l''aéroport de Marrakech, Résidence Miftah se distingue par son architecture moderne et ses finitions soignées. Ce projet signé Chafik Immobilier a été conçu pour offrir un équilibre parfait entre confort, sécurité et accessibilité. Chaque espace a été pensé pour répondre aux besoins des familles et des investisseurs à la recherche d''un bien de qualité dans un quartier en plein essor. Vous y trouverez des appartements lumineux, des duplex spacieux et des espaces commerciaux stratégiquement situés. Profitez d''un environnement calme, entouré de commodités essentielles: écoles, supermarchés, hôpital, mosquée et aéroport. Les résidents bénéficient également de systèmes de sécurité modernes, ascenseurs performants et cuisines entièrement équipées, avec une vue dégagée sur la ville. Résidence Miftah, c''est bien plus qu''un projet immobilier, c''est un lieu où la qualité de vie prend tout son sens.', 'Marrakech', 'M''Hamid 9', 'Lotissement Miftah, M''Hamid 9, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'mixte', 'mixte', 'pret_a_livrer', 'en_commercialisation', 90, NULL, NULL, 'https://media.chridari.ma/90d1be7b-6d63-4326-b760-07b2b3520603/images/01K94DAVGHE2GVYS95ZYF2XEJ0-medium.jpg', $j$["https://media.chridari.ma/90d1be7b-6d63-4326-b760-07b2b3520603/images/01K94DAVGHE2GVYS95ZYF2XEJ0-medium.jpg", "https://media.chrida